import { useState } from "react";

export default function Navbar() {
  const [isOpen, setIsOpen] = useState(false);

  return (
    <nav className="bg-white shadow-md fixed top-0 left-0 right-0 z-50">
      <div className="container mx-auto px-4 py-3 flex justify-between items-center">
        <h1 className="text-2xl font-bold text-green-800">Sikkim Monasteries</h1>
        <button
          className="md:hidden text-green-800"
          onClick={() => setIsOpen(!isOpen)}
        >
          ☰
        </button>
        <ul className="hidden md:flex space-x-6 text-green-900 font-medium">
          <li><a href="#home" className="hover:text-green-600">Home</a></li>
          <li><a href="#about" className="hover:text-green-600">About</a></li>
          <li><a href="#monasteries" className="hover:text-green-600">Monasteries</a></li>
          <li><a href="#contact" className="hover:text-green-600">Contact</a></li>
        </ul>
      </div>
      {isOpen && (
        <ul className="md:hidden bg-white px-6 py-4 space-y-3 text-green-900">
          <li><a href="#home">Home</a></li>
          <li><a href="#about">About</a></li>
          <li><a href="#monasteries">Monasteries</a></li>
          <li><a href="#contact">Contact</a></li>
        </ul>
      )}
    </nav>
  );
}
